import{_ as e,o as a,c as r,a2 as i}from"./chunks/framework.CqGS6Fr9.js";const u=JSON.parse('{"title":"Тестирование и приёмка","description":"","frontmatter":{"pageId":"developers/testing","contentRevision":2},"headers":[],"relativePath":"ru/developers/testing.md","filePath":"ru/developers/testing.md"}'),o={name:"ru/developers/testing.md"};function d(l,t,n,c,s,h){return a(),r("div",null,[...t[0]||(t[0]=[i('<h1 id="тестирование-и-приемка" tabindex="-1">Тестирование и приёмка <a class="header-anchor" href="#тестирование-и-приемка" aria-label="Permalink to &quot;Тестирование и приёмка&quot;">​</a></h1><p>Применимость: Rimlink 0.8.1 · RimWorld 1.7 · протокол 1.</p><h2 id="usage" tabindex="-1">Как пользоваться <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Как пользоваться {#usage}&quot;">​</a></h2><p>Сначала воспроизведи сценарий и увидь падающий целевой тест, затем минимальное исправление и повтор. Серверные тесты используют настоящий WebApplicationFactory; client-core тесты общаются с тестовым сервером. Полный набор: dotnet test Rimlink.sln -nologo -v q.</p><p>Поток Open вернулся — это ещё не peer attached: утверждай по полученным событиям. Таймауты измеряй Stopwatch, не DateTime.UtcNow. Для timing-изменений повтори набор на Linux/двух CPU при доступности среды.</p><p>Игровую логику проверяй двумя изолированными экземплярами host/guest, отдельными savedata и сервером/портом. BridgeTools/RimBridge — только доступный dev-инструмент, не зависимость релиза. Запиши фактически выполненные шаги и результат в manual checklist; сценарий сам по себе не является PASS.</p><p>Wiki: test:checks → check:content → check:reference → check:drift -- --base &lt;commit&gt; → build → check:links, затем реальный браузер/поиск/мобильная навигация.</p><h2 id="test-matrix" tabindex="-1">Какая проверка отвечает на какой вопрос? <a class="header-anchor" href="#test-matrix" aria-label="Permalink to &quot;Какая проверка отвечает на какой вопрос? {#test-matrix}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Проверка</th><th>Подтверждает</th><th>Не подтверждает</th></tr></thead><tbody><tr><td>Solution build/tests</td><td>Core/server contracts, storage, mocked boundary scenarios</td><td>Игровой UI/Scribe/пешки</td></tr><tr><td>Build-ClientMod</td><td>Компиляцию против установленной игры</td><td>Успешный двухсторонний сценарий</td></tr><tr><td>Два изолированных клиента</td><td>Реальное исполнение конкретных шагов</td><td>Все моды/DLC/GOG-комбинации</td></tr><tr><td>Wiki validators/build</td><td>Структуру, ссылки, inventory</td><td>Верность смысла статьи</td></tr><tr><td>Browser acceptance</td><td>Поиск, навигацию, layout в проверенных размерах</td><td>Все браузеры и настоящий OS zoom</td></tr></tbody></table><p>Для bugfix сначала наблюдай RED на исходном сценарии, затем GREEN. Для сетевого потока жди полученное событие, не возврат Open. Deadline измеряй Stopwatch; для time/race-изменений повтори Linux/two-CPU, если доступно.</p><h2 id="acceptance-record" tabindex="-1">Как записать воспроизводимую приёмку? <a class="header-anchor" href="#acceptance-record" aria-label="Permalink to &quot;Как записать воспроизводимую приёмку? {#acceptance-record}&quot;">​</a></h2><p>Укажи commit, версии, отдельный DataDir/порт, host/guest savedata и исходное состояние. Запиши действия, ожидаемые и наблюдавшиеся результаты, id операций, return mail и сохранение/повторный вход. Снимок UI без проверки серверного результата не доказывает escrow.</p><p>Для coop проверь назначенную/неназначенную пешку, выход, отзыв и rollback. Для экономики — неизвестный ответ и исходный replay. Не запускай чужие игры и не обнуляй общий Player.log. Незавершённый сценарий отмечай partial, не PASS.</p><h2 id="limits" tabindex="-1">Ограничения и безопасность <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Ограничения и безопасность {#limits}&quot;">​</a></h2><p>Не запускай второй сервер на данных живого сервера и не останавливай чужую игру. Общий Player.log может перезаписываться экземплярами. Не называй незапущенный тест успешным.</p><h2 id="related" tabindex="-1">См. также <a class="header-anchor" href="#related" aria-label="Permalink to &quot;См. также {#related}&quot;">​</a></h2><ul><li><a href="./build">Сборка проекта</a></li><li><a href="./contributing">Вклад и сопровождение wiki</a></li><li><a href="./../admins/troubleshooting">Проблемы администратора</a></li></ul>',17)])])}const m=e(o,[["render",d]]);export{u as __pageData,m as default};
